import Tooltip from "./tooltip";
var Clipboard = /** @class */ (function () {
    function Clipboard(element, text) {
        this.element = typeof element == 'object' ? element : document.querySelector(element);
        this.text = text || this.element.getAttribute("data-text");
    }
    Clipboard.prototype._copy = function (text) {
        var textArea = document.createElement("textarea");
        textArea.value = text;
        textArea.style.top = "0";
        textArea.style.left = "0";
        textArea.style.position = "fixed";
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        var result;
        try {
            result = document.execCommand('copy');
            //console.log('copied using exceCommand');
        }
        catch (err) {
            console.error('failed to copy', err);
            result = false;
        }
        finally {
            document.body.removeChild(textArea);
        }
        if (result) {
            this.ShowMsg("Copied!");
        }
    };
    Clipboard.prototype.ShowMsg = function (msg) {
        var tip = new Tooltip(this.element, msg);
        var html = tip.create('copy-alert').html();
        document.body.appendChild(html);
        var callback = function (element) {
            element.remove();
        };
        setTimeout(function () {
            callback(html);
        }, 1000);
    };
    Clipboard.prototype.Copy = function () {
        var _this = this;
        if (!navigator.clipboard) {
            return this._copy(this.text);
        }
        return navigator.clipboard.writeText(this.text).then(function () {
            _this.ShowMsg("Copied!");
        }, function (err) {
            console.error('failed to copy text: ', err);
        });
    };
    return Clipboard;
}());
export default Clipboard;
